const m = String.raw;

function equation(slide, title, tex, purpose, read, symbols, example, insight) {
  return {slide, formula:[title, tex, 'Source slide ' + slide + '.'], context:{purpose, read, symbols, example, insight}};
}

export const detectionEquations = {
  corners: equation(13, 'Corner offsets', m`y_{\mathrm{off}}=y_{\mathrm{box}}-y_{\mathrm{anchor}},\qquad
    y_{\mathrm{box}}=y_{\mathrm{anchor}}+y_{\mathrm{off}}`,
    'Encode or recover the four corners using a reference rectangle.',
    'Subtract the anchor edge from the object edge. Add the correction back to recover the box.',
    [[m`$y_{\mathrm{box}}$`, 'Four object-box coordinates.'], [m`$y_{\mathrm{anchor}}$`, 'The corresponding anchor coordinates.'], [m`$y_{\mathrm{off}}$`, 'Four signed edge corrections.']],
    m`Anchor $(0,0,8,8)$ and box $(2,1,6,7)$ give $(2,1,-2,-1)$ in corner order.`,
    'Both lists must use the same coordinate order. A negative right-edge offset moves that edge left.'),
  grid: equation(14, 'Counting grid locations and anchors', m`N_{\mathrm{anchors}}=\sum_j G_{xj}G_{yj}T_j`,
    'Count the references from all grids. This notation names the quantities in the slide’s count.',
    'Multiply columns by rows by templates per location, then add across grids.',
    [[m`$G_{xj},G_{yj}$`,'Columns and rows on grid j.'],[m`$T_j$`,'Templates at each grid location.']],
    m`A $3\times2$ grid with five templates per point yields $3\cdot2\cdot5=30$ anchors.`,
    'Adding another ratio increases the number of templates without changing the grid spacing.'),
  shapes: equation(16, 'Aspect ratio and anchor dimensions', m`(w_i,h_i)=\left(w s_{xj}\sqrt{a_i},\;h s_{yj}/\sqrt{a_i}\right)`,
    'Make a wider or taller anchor at the same base scale.',
    'Multiply the base width by the square root of the ratio and divide the base height by it.',
    [[m`$w,h$`,'Image width and height.'],[m`$s_{xj},s_{yj}$`,'Width and height scale at level j.'],[m`$a_i$`,'Shape multiplier. It is the resulting aspect ratio for a square base.']],
    m`If the base is $8\times8$ and $a_i=4$, the result is $16\times4$. Both areas are 64.`,
    'Changing only the aspect multiplier changes the shape while preserving the base area.'),
  iou: equation(22, 'Intersection over Union (IoU)', m`\operatorname{IoU}(A,B)=\frac{|A\cap B|}{|A\cup B|}
    =\frac{|A\cap B|}{|A|+|B|-|A\cap B|}`,
    'Measure how well two boxes line up on a scale from zero to one.',
    'Divide the shared area by the area covered by either box.',
    [[m`$A,B$`,'The two rectangles.'],[m`$|A\cap B|$`,'Area covered by both.'],[m`$|A\cup B|$`,'Area covered by at least one box.']],
    m`Areas 16 and 16 with 8 in common give union $16+16-8=24$ and IoU $8/24=1/3$.`,
    'IoU is used for training matches, duplicate suppression, and evaluation. The pair of boxes being compared changes.'),
  ssdLoss: equation(28, 'SSD classification and offset loss', m`\mathcal L=\frac{\mathcal L_{\mathrm{cls}}+
    \alpha\sum_i [u_i\ge1]\,\mathcal L_{\mathrm{off},i}}{N}`,
    'Combine the selected class losses with the box losses for positive anchors.',
    'Sum classification and weighted localization, then divide by the number of matched anchors.',
    [[m`$\mathcal L_{\mathrm{cls}}$`,'Sum of classification losses over selected anchors.'],[m`$\mathcal L_{\mathrm{off},i}$`,'Box loss for anchor i, counted only for positives.'],[m`$[u_i\ge1]$`,'1 for a positive label, 0 for background.'],[m`$N,\alpha$`,'Positive anchor count and localization weight.']],
    m`With $N=2$, classification sum 4, positive box loss sum 2 and $\alpha=1$, the total is $(4+2)/2=3$.`,
    'The per-anchor index makes the slide’s positive-only gate explicit. The original SSD sets loss to zero when there are no matches.'),
  encode: equation(29, 'Normalized box encoding', m`y_{\mathrm{gt}}=\left(
    \frac{c_{bx}-c_{ax}}{w_a},\;\frac{c_{by}-c_{ay}}{h_a},\;\log\frac{w_b}{w_a},\;\log\frac{h_b}{h_a}\right)`,
    'Put center shifts and size changes in units relative to the anchor.',
    'Divide the two center shifts by the anchor dimensions. Take the logs of the two size ratios.',
    [[m`$c_{ax},c_{ay},w_a,h_a$`,'Anchor center, width and height.'],[m`$c_{bx},c_{by},w_b,h_b$`,'Ground-truth box center, width and height.'],[m`$y_{\mathrm{gt}}$`,'The encoded four-component training target.']],
    m`For anchor $(4,4,8,8)$ and object $(8,4,16,8)$ in center-size form, the target is $(1/2,0,\log 2,0)$.`,
    'To decode, multiply the normalized shifts by anchor size and add the center. Exponentiate the size terms before multiplying by anchor size.'),
  scale: equation(30, 'Extra scaling of encoded offsets', m`y_{\mathrm{gt}}^{\mathrm{scaled}}=\left(
    \frac{y_{\mathrm{gt},x}}{\sigma_x},\frac{y_{\mathrm{gt},y}}{\sigma_y},
    \frac{y_{\mathrm{gt},w}}{\sigma_w},\frac{y_{\mathrm{gt},h}}{\sigma_h}\right)`,
    'Rescale each component of the normalized target by the corresponding slide constant.',
    'Divide the x, y, width and height components by their own scaling factors.',
    [[m`$y_{\mathrm{gt},x},\ldots,y_{\mathrm{gt},h}$`,'Offsets from slide 29, before extra scaling.'],[m`$\sigma_x,\sigma_y,\sigma_w,\sigma_h$`,'Slide defaults 0.1, 0.1, 0.2 and 0.2.']],
    m`An encoded x shift of $1/10$ becomes $(1/10)/(1/10)=1$.`,
    'The superscript distinguishes the two stages of encoding. Multiply by these factors before decoding.'),
  smooth: equation(31, 'Smooth L1', m`L1_{\mathrm{smooth}}(u)=
    \begin{cases}(\sigma u)^2/2 & |u|<1/\sigma^2,\\
    |u|-1/(2\sigma^2)&\text{otherwise.}\end{cases}`,
    'Turn one offset error into a loss with a smooth center and linear tails.',
    'Use a square near zero and absolute error minus a constant in the tails.',
    [[m`$u$`,'One predicted offset minus its target.'],[m`$\sigma>0$`,'Controls the width of the quadratic region. This is the loss parameter.']],
    m`For $\sigma=1$, error $-1/2$ gives $1/8$ and error $-2$ gives $2-1/2=3/2$.`,
    'Large errors have a bounded slope. This is a regression loss, while L1 in Regularization penalizes weights.'),
  softNms: equation(41, 'Gaussian Soft-NMS score update', m`p_i\leftarrow p_i\exp\left[-\frac{\operatorname{IoU}(\mathcal M,b_i)^2}{\sigma}\right]`,
    'Reduce a remaining prediction’s score based on its overlap with the current winner.',
    'Multiply its score by an exponential that gets smaller as the squared overlap grows.',
    [[m`$\mathcal M,b_i$`,'Current highest-scoring box and another candidate.'],[m`$p_i$`,'Score of the other candidate.'],[m`$\sigma>0$`,'Controls the amount of decay.']],
    m`IoU $1/2$ and $\sigma=1/4$ multiply the score by $e^{-1}$. At IoU zero the multiplier is 1.`,
    'Update the ranking after scores change. Hard NMS deletes boxes when their IoU reaches the cutoff.'),
  meanIou: equation(42, 'Mean best IoU in the deck', m`\mathrm{mIoU}=\frac1{n_{\mathrm{box}}}
    \sum_{i=1}^{n_{\mathrm{box}}}\max_{1\le j\le n_{\mathrm{pred}}}\operatorname{IoU}(b_i,d_j)`,
    'Summarize how well the predicted boxes cover each annotated object in the slide’s simple metric.',
    'Find the best predicted overlap for every ground-truth box, then average.',
    [[m`$b_i,d_j$`,'Ground-truth box i and predicted detection j.'],[m`$n_{\mathrm{box}},n_{\mathrm{pred}}$`,'Counts of ground-truth and predicted boxes.']],
    m`Best overlaps $3/4$ and $1/4$ average to $1/2$.`,
    'Adding a distant false alarm can leave this score unchanged. Precision would account for it.'),
  precision: equation(43, 'Precision and recall', m`\mathrm{precision}=\frac{tp}{tp+fp},\qquad
    \mathrm{recall}=\frac{tp}{tp+fn}`,
    'Separate the accuracy of reported boxes from the coverage of labeled objects.',
    'Divide matches by the number of reports for precision, and by the number of labeled objects for recall.',
    [[m`$tp$`,'Correct matched detections.'],[m`$fp$`,'Reported detections without a valid unused match.'],[m`$fn$`,'Annotated objects left unmatched.']],
    m`With $tp=2,fp=2,fn=1$, precision is $2/4=1/2$ and recall is $2/3$.`,
    'A duplicate can become a false positive once the object has already been matched.'),
  ap: equation(48, 'VOC 2007 eleven-point AP', m`\mathrm{AP}_{07}=\frac1{11}\sum_{r\in\{0,0.1,\ldots,1\}}P_r,
    \qquad P_r=\max_{\tilde r\ge r}P(\tilde r)`,
    'Summarize a ranked detection list for a class under the historical VOC 2007 protocol.',
    'At each of eleven recall levels, use the highest precision at that recall or above and average.',
    [[m`$r,\tilde r$`,'Requested recall and a recall actually reached by a confidence cutoff.'],[m`$P(\tilde r)$`,'Precision at a cutoff reaching that recall.'],[m`$P_r$`,'Interpolated precision, set to zero if no cutoff reaches r.']],
    m`If one correct report achieves precision 1 at recall $1/2$ and higher recall is never reached, AP is $6/11$.`,
    'The six contributing recall levels are 0 through 0.5. COCO uses a different AP protocol.'),
  roi: equation(56, 'RoI pooling bin dimensions', m`\text{bin width}\approx w/W,\qquad \text{bin height}\approx h/H`,
    'Divide a projected region into the fixed grid expected by the prediction head.',
    'Divide the region’s width by the number of output columns and its height by the number of rows.',
    [[m`$h,w$`,'Height and width of the region on the feature map.'],[m`$H,W$`,'Target height and width of the pooled grid.']],
    m`A region $h=4,w=6$ with $H=2,W=2$ gives four bins, each 2 cells high and 3 wide.`,
    'Max-pool each bin independently in each channel. Real pooling quantizes bin boundaries.'),
  fastLoss: equation(60, 'Fast R-CNN loss per RoI', m`\mathcal L=-\log p_u+\alpha[u\ge1]\mathcal L_{\mathrm{off}}`,
    'Train class prediction and box refinement on a sampled region.',
    'Penalize low probability of the true class and add box error only for foreground.',
    [[m`$p_u$`,'Predicted probability of the true class u.'],[m`$[u\ge1]$`,'Foreground indicator.'],[m`$\alpha,\mathcal L_{\mathrm{off}}$`,'Box loss weight and box error.']],
    m`A background RoI with $p_0=1/2$ contributes $-\log(1/2)=\log 2$ from classification alone.`,
    'The structure resembles SSD’s loss, applied to a proposed region.'),
  rpnCount: equation(68, 'RPN anchor and output counts', m`N_{\mathrm{anchors}}=WHk,\qquad
    (n_{\mathrm{cls}},n_{\mathrm{off}})=(2k,4k)\ \text{per location}`,
    'Count how many references and predictions the sliding RPN head makes.',
    'Multiply the map’s locations by anchors per location. Use two objectness and four box outputs per anchor.',
    [[m`$W,H$`,'Feature map width and height.'],[m`$k$`,'Number of anchor templates at each location.'],[m`$n_{\mathrm{cls}},n_{\mathrm{off}}$`,'Class-score and offset counts per location.']],
    m`A $4\times3$ map with $k=9$ has 108 anchors and makes 18 objectness scores and 36 offsets per location.`,
    'The final head predicts the actual object categories.'),
  rpnLoss: equation(72, 'RPN objectness and box loss', m`\mathcal L=\frac{\mathcal L_{\mathrm{cls}}}{N_{\mathrm{cls}}}
    +\frac{\lambda}{N_{\mathrm{reg}}}\sum_i[u_i\ge1]\mathcal L_{\mathrm{off},i}`,
    'Train the two RPN outputs with separate normalizers.',
    'Average objectness loss by its normalizer and add weighted offset loss from positive anchors.',
    [[m`$N_{\mathrm{cls}},N_{\mathrm{reg}}$`,'Classification minibatch size and regression normalizer (anchor locations in the slide).'],[m`$\lambda$`,'Relative weight for localization.'],[m`$[u_i\ge1]$`,'Positive anchor indicator.']],
    m`With class sum 8 over 4, positive box sum 3 over 6, and $\lambda=2$, the loss is $8/4+2(3/6)=3$.`,
    'Ignored anchors are skipped before this calculation. Negatives still train objectness.'),
  fpn: equation(84, 'FPN lateral addition', m`M_k=\operatorname{Conv}_{1\times1}(C_k)+\operatorname{Upsample}_{2\times}(M_{k+1})`,
    'Combine backbone detail with coarser top-down information. The notation names the merged intermediate map.',
    'Project the backbone channels, enlarge the coarse map, then add corresponding values.',
    [[m`$C_k$`,'Backbone map at level k.'],[m`$M_{k+1}$`,'Coarser merged map.'],[m`$M_k$`,'Current merged map, used to produce pyramid output Pₖ.']],
    m`A $4\times4$ coarse map upsamples to $8\times8$ to combine with an $8\times8$ lateral map.`,
    'The original FPN applies a 3-by-3 convolution after the merge to produce each output map.'),
  roiLevel: equation(87, 'FPN RoI level assignment', m`k=\left\lfloor k_0+\log_2\!\left(\frac{\sqrt{wh}}{224}\right)\right\rfloor,
    \qquad k_0=4`,
    'Choose the feature-map resolution for pooling a given proposal.',
    'Compare the proposal’s geometric mean size with 224. Take the base-2 log, add four and round down.',
    [[m`$w,h$`,'Proposal width and height in image pixels.'],[m`$k,k_0$`,'Assigned level and reference level.']],
    m`A $112\times112$ proposal gives $k=4+\log_2(1/2)=3$, so use $P_3$.`,
    'The original paper specifies the base and floor. Constrain the result to available RoI levels.'),
  ce: equation(95, 'Binary cross-entropy and true-label probability', m`p_t=\begin{cases}p&y=1\\1-p&y=-1\end{cases},
    \qquad \mathrm{CE}(p_t)=-\log p_t`,
    'Measure how much probability the classifier assigned to the observed label.',
    'Use the foreground probability if foreground is true. Otherwise use its complement. Take the negative log.',
    [[m`$p,p_t$`,'Foreground probability and true-label probability.'],[m`$y$`,'The true label, +1 for foreground and −1 for background here.']],
    m`A background location with $p=1/4$ has $p_t=3/4$ and loss $-\log(3/4)$.`,
    'The same true-label probability drives focal loss.'),
  focal: equation(98, 'Balanced focal loss', m`\mathrm{FL}(p_t)=-\alpha_t(1-p_t)^\gamma\log p_t`,
    'Keep dense training focused on examples the classifier still finds difficult.',
    'Multiply cross-entropy by a class weight and a factor that shrinks for confident correct predictions.',
    [[m`$p_t$`,'Probability of the true label.'],[m`$\alpha_t$`,'Weight for that true class.'],[m`$\gamma\ge0$`,'Controls downweighting by difficulty.']],
    m`For $p_t=3/4$ and $\gamma=2$, the modulating factor is $(1/4)^2=1/16$ before class weighting.`,
    m`With $\gamma=0$, the difficulty factor disappears. With $\alpha_t$ still present, the result is class-weighted cross-entropy.`),
  prior: equation(100, 'RetinaNet initial classification bias', m`b=-\log\frac{1-\pi}{\pi},
    \qquad \operatorname{sigmoid}(b)=\pi`,
    'Set a low initial foreground probability to avoid an early flood of false positives in training.',
    'Set the bias to the log-odds of the desired starting probability.',
    [[m`$\pi$`,'Desired initial foreground probability, 0.01 in the slide.'],[m`$b$`,'Bias of the final classification layer when other inputs are near zero.']],
    m`If $\pi=1/4$, then $b=-\log 3$ and the sigmoid is $1/(1+3)=1/4$.`,
    'This is an initialization choice, while focal loss continues to weight examples as predictions change.'),
  projection: equation(108, 'FSAF projection and supervision regions', m`\begin{aligned}
    b_p^l &= b/2^l=(x_p^l,y_p^l,w_p^l,h_p^l)\\
    b_e^l &= (x_p^l,y_p^l,\epsilon_e w_p^l,\epsilon_e h_p^l)\\
    b_i^l &= (x_p^l,y_p^l,\epsilon_i w_p^l,\epsilon_i h_p^l)
    \end{aligned}`,
    'Find which locations can learn an object on a given pyramid level.',
    'Project to feature units and shrink width and height around the same center.',
    [[m`$b_p^l$`,'Projected object box in center-size form.'],[m`$b_e^l,b_i^l$`,'Effective box and enclosing ignoring box.'],[m`$\epsilon_e,\epsilon_i$`,'Fractions of projected width and height, typically 0.2 and 0.5.']],
    m`If the projected box measures $10\times10$, the effective box is $2\times2$ and the ignoring box is $5\times5$.`,
    'Training skips the classification gradient for points in the band.'),
  fsafOffsets: equation(112, 'FSAF side-distance targets and decoding', m`\begin{aligned}
    \text{target}_{i,j}^l &= \mathbf d_{i,j}^l/S\\
    \hat{\mathbf d}_p^l &= 2^l(i-So_t,j-So_l,\,i+So_b,j+So_r)
    \end{aligned}`,
    'Translate a point’s four predictions into a box in image coordinates.',
    'Recover feature-level distances, subtract toward the top and left, add toward the bottom and right, then scale to image units.',
    [[m`$(i,j)$`,'Feature-map row and column.'],[m`$\mathbf d_{i,j}^l$`,'Target distances to the top, left, bottom and right.'],[m`$o_t,o_l,o_b,o_r$`,'Predicted normalized distances at that point.'],[m`$S,2^l$`,'Normalization constant (4 in the slide) and level stride.']],
    m`At $(4,4)$ with all four predictions $1/2$ and $S=4$, the projected corners are $(2,2)$ and $(6,6)$ before multiplying by the stride.`,
    'FSAF uses row, column coordinates here. FCOS lists horizontal and vertical distances in a different order.'),
  iouLoss: equation(111, 'UnitBox IoU loss', m`L_{\operatorname{IoU}}(B,\hat B)=-\ln\operatorname{IoU}(B,\hat B)`,
    'Score the fit of the predicted rectangle as a whole.',
    'Calculate overlap, then take its negative natural log. Higher overlap gives smaller loss.',
    [[m`$B,\hat B$`,'Target and predicted rectangles with positive overlap for this expression.']],
    m`IoU $1/2$ gives $\ln 2$. Perfect overlap gives zero.`,
    'All four edges interact through the same overlap ratio.'),
  fsafLevel: equation(114, 'FSAF feature level selection', m`\begin{aligned}
    L_{\mathrm{FL}}^I(l)&=\frac{\sum_{i,j\in b_e^l}\mathrm{FL}(l,i,j)}{N(b_e^l)}\\
    L_{\mathrm{IoU}}^I(l)&=\frac{\sum_{i,j\in b_e^l}L_{\mathrm{IoU}}(l,i,j)}{N(b_e^l)}\\
    l^*&=\arg\min_l\left(L_{\mathrm{FL}}^I(l)+L_{\mathrm{IoU}}^I(l)\right)
    \end{aligned}`,
    'Choose which feature level learns a particular instance during training.',
    'Average the two losses inside the effective region, add them, and choose the level with the smallest sum.',
    [[m`$I,l$`,'One annotated instance and a candidate level.'],[m`$b_e^l,N(b_e^l)$`,'The effective box and number of locations inside it.'],[m`$l^*$`,'Index of the level selected for this object.']],
    m`Totals of $1/2+1/4$ at level 3 and $1/4+1/4$ at level 4 give $l^*=4$.`,
    'In the second sum, the term denotes the IoU loss. Direct overlap is a similarity and would reward worse boxes if minimized.'),
  backproject: equation(123, 'FCOS point back-projection', m`(x',y')=(s/2+xs,\;s/2+ys)`,
    'Find the image coordinate corresponding to a feature point.',
    'Multiply each grid index by the stride, then move half a stride to the cell center.',
    [[m`$(x,y)$`,'Zero-based grid location.'],[m`$(x\prime,y\prime)$`,'Corresponding image coordinate.'],[m`$s$`,'Image pixels between neighboring feature locations.']],
    m`With $s=8$, feature point $(1,2)$ maps to $(12,20)$.`,
    'Assignment uses the point on the original image to test whether it lies in a ground-truth box.'),
  fcosOffsets: equation(125, 'FCOS left, top, right, bottom targets', m`\mathbf t^*=(x'-x_0^{(i)},\;y'-y_0^{(i)},\;x_1^{(i)}-x',\;y_1^{(i)}-y')`,
    'Measure the four side distances for a point inside its assigned box.',
    'Subtract the left and top edge from the point. Subtract the point from the right and bottom edges.',
    [[m`$(x',y')$`,'Point projected into the image.'],[m`$(x_0^{(i)},y_0^{(i)}),(x_1^{(i)},y_1^{(i)})$`,'Top-left and bottom-right corners of object i.'],[m`$\mathbf t^*$`,'Distances in left, top, right, bottom order.']],
    m`Point $(4,5)$ inside corners $(1,2)$ and $(9,7)$ gives $(3,3,5,2)$.`,
    'You can reconstruct both corners from the point and the four distances.'),
  fcosLoss: equation(127, 'FCOS classification and regression loss', m`\begin{aligned}
    L&=\frac1{N_{\mathrm{pos}}}\sum_{x,y}L_{\mathrm{cls}}(\mathbf p_{x,y},c^*_{x,y})\\
     &\quad+\frac{\lambda}{N_{\mathrm{pos}}}\sum_{x,y}[c^*_{x,y}\ge1]L_{\mathrm{reg}}(\mathbf t_{x,y},\mathbf t^*_{x,y})
    \end{aligned}`,
    'Combine focal classification loss with positive-only box regression.',
    'Sum class loss and weighted IoU loss, then normalize by the number of positives.',
    [[m`$N_{\mathrm{pos}}$`,'Number of foreground locations, assumed positive for the expression.'],[m`$\mathbf p_{x,y},c^*_{x,y}$`,'Class scores and the target class at a location.'],[m`$\mathbf t_{x,y},\mathbf t^*_{x,y}$`,'Predicted and target box distances.'],[m`$\lambda$`,'Regression weight, 1 in the slide.']],
    m`Two positives, focal loss sum 3, and positive regression sum 1 give $(3+1)/2=2$ when $\lambda=1$.`,
    'The separate centerness branch adds its own binary cross-entropy loss.'),
  fcosRange: equation(128, 'FCOS scale range for a point', m`m_{i-1}\le\max(l^*,t^*,r^*,b^*)\le m_i`,
    'Check whether a feature level accepts the size of the box measured from this point.',
    'Find the farthest side and compare that distance with both limits for the level.',
    [[m`$l^*,t^*,r^*,b^*$`,'Four ground-truth side distances from the image point.'],[m`$m_{i-1},m_i$`,'Lower and upper distance limits for level i.']],
    m`For $(10,20,80,40)$, the maximum is 80. The point passes the $P_4$ range $[64,128]$.`,
    'This follows the cited FCOS paper. Slide 128 writes a minimum for the lower-bound test.'),
  centerness: equation(129, 'FCOS centerness target', m`\mathrm{centerness}^*=\sqrt{
    \frac{\min(l^*,r^*)}{\max(l^*,r^*)}\,
    \frac{\min(t^*,b^*)}{\max(t^*,b^*)}}`,
    'Teach a separate head to score how central a positive point is within its target box.',
    'Compare the shorter distance to the longer one on each axis. Multiply the two ratios and take the square root.',
    [[m`$l^*,r^*$`,'Distances from the point to the left and right sides.'],[m`$t^*,b^*$`,'Distances to the top and bottom sides.']],
    m`With $(l^*,t^*,r^*,b^*)=(1,2,4,2)$, the target is $\sqrt{(1/4)(1)}=1/2$.`,
    'At inference, the predicted centerness adjusts the class score before selecting the final boxes.')
};
